#!/usr/bin/env bash
# Builds the fuzz driver against libogg sources with full sanitizers.
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"

# Reuse the platform type header generated by the baseline cmake build.
CFG="$ROOT/build-baseline/include/ogg/config_types.h"
if [[ ! -f "$CFG" ]]; then
  echo "baseline build missing; run cmake -DBUILD_TESTING=ON first" >&2
  exit 1
fi

SAN="-fsanitize=address,undefined -fno-sanitize-recover=all \
     -fno-omit-frame-pointer -g -O1"
# LSan rides along with ASan on Linux/glibc.

set -x
gcc $SAN -I"$ROOT/include" -I"$ROOT/build-baseline/include" \
  "$ROOT/src/framing.c" "$ROOT/src/bitwise.c" "$HERE/fuzz_parse.c" \
  -o "$HERE/fuzz_parse"

# A second binary with CRC enforcement disabled, used only to exercise
# parser paths that are otherwise unreachable behind bad-checksum pages
# (page-length desync, cyclic chains on corrupt pages).
gcc $SAN -DDISABLE_CRC -I"$ROOT/include" -I"$ROOT/build-baseline/include" \
  "$ROOT/src/framing.c" "$ROOT/src/bitwise.c" "$HERE/fuzz_parse.c" \
  -o "$HERE/fuzz_parse_nocrc"
